  prependProperty(name: string): void {
    this._segments.unshift(`.${name}`);
  }

  /**
   * Insert the access to the item at `index` before the {@link path}.
   */
  prependIndex(index: number): void {
    this._segments.unshift(`[${index}]`);
  }
